text:
{
  "items": [
    {
      "stem": "小明去文具店买笔记本，每本笔记本4元，他买了6本，一共需要付多少钱？",
      "answer": "24元",
      "solution": "单价乘以数量等于总价，即 4 × 6 = 24（元）。"
    },
    {
      "stem": "老师把18个苹果平均分给3个小朋友，每个小朋友分到几个苹果？",
      "answer": "6个",
      "solution": "总数除以份数等于每份的数量，即 18 ÷ 3 = 6（个）。"
    },
    {
      "stem": "一盒彩笔有8支，学校买了5盒这样的彩笔，一共有多少支彩笔？",
      "answer": "40支",
      "solution": "每盒的数量乘以盒数等于总数，即 8 × 5 = 40（支）。"
    },
    {
      "stem": "停车场里有24辆小汽车，如果每排停6辆，可以停几排？",
      "answer": "4排",
      "solution": "车辆总数除以每排的数量等于排数，即 24 ÷ 6 = 4（排）。"
    },
    {
      "stem": "一只青蛙每天吃7只害虫，它一周（7天）能吃多少只害虫？",
      "answer": "49只",
      "solution": "每天吃的数量乘以天数等于总数，即 7 × 7 = 49（只）。"
    },
    {
      "stem": "妈妈买了35颗糖果，打算装在袋子里，每袋装5颗，需要多少个袋子？",
      "answer": "7个",
      "solution": "糖果总数除以每袋的数量等于袋子数，即 35 ÷ 5 = 7（个）。"
    },
    {
      "stem": "图书馆新进了9套故事书，每套有6本，图书馆一共新进多少本故事书？",
      "answer": "54本",
      "solution": "套数乘以每套的本数等于总本数，即 9 × 6 = 54（本）。"
    },
    {
      "stem": "有32名同学参加跳绳比赛，平均分成4组，每组有多少名同学？",
      "answer": "8名",
      "solution": "总人数除以组数等于每组人数，即 32 ÷ 4 = 8（名）。"
    }
  ]
}
